/* Kontenart aus der IKR-Nummer ableiten */
function kontoArt(nr){
  const n = String(nr||'').trim();
  const k = n.charAt(0);
  if (k === '0' || k === '1') return 'aktiv';
  if (k === '2') return 'aktiv';
  if (k === '3' || k === '4') return 'passiv';
  if (k === '5') return 'ertrag';
  if (k === '6' || k === '7') return 'aufwand';
  return 'abschluss';
}
const ART_NAME = {aktiv:'Aktivkonto', passiv:'Passivkonto', aufwand:'Aufwandskonto', ertrag:'Ertragskonto', abschluss:'Abschlusskonto'};
/* Auf welcher Seite steht eine Mehrung / ein Zugang? */
const MEHRUNG = {aktiv:'soll', passiv:'haben', aufwand:'soll', ertrag:'haben', abschluss:'soll'};

function artRegel(nr){
  const a = kontoArt(nr);
  if (a === 'aktiv')   return 'Aktivkonten: Zugänge im Soll, Abgänge im Haben.';
  if (a === 'passiv')  return 'Passivkonten: Zugänge im Haben, Abgänge im Soll.';
  if (a === 'aufwand') return 'Aufwandskonten werden im Soll gebucht (Ausnahme: Korrekturen wie Skonto im Haben).';
  if (a === 'ertrag')  return 'Ertragskonten werden im Haben gebucht (Ausnahme: Korrekturen wie Skonto im Soll).';
  return '';
}
