function verwechslungsText(a,b){
  const x = String(a), y = String(b);
  const t = VERWECHSLUNG.find(v => (v.p[0]===x && v.p[1]===y) || (v.p[0]===y && v.p[1]===x));
  return t ? t.t : null;
}

