const SUMMENTEXT = {gleich:'Die Bilanzsumme bleibt unverändert.', steigt:'Die Bilanzsumme steigt.', sinkt:'Die Bilanzsumme sinkt.'};

/* Vorgangsart aus Positionen und Richtungen ableiten */
function vorgangsartAbleiten(positionen){
  if (!positionen || positionen.length < 2) return null;
  const seiten = positionen.map(p => posSeite(p.name));
  if (seiten.some(x => !x)) return null;
  const nurAktiv  = seiten.every(x => x === 'aktiv');
  const nurPassiv = seiten.every(x => x === 'passiv');
  const zu = positionen.filter(p => p.richtung === 'zu').length;
  const ab = positionen.filter(p => p.richtung === 'ab').length;
  if (nurAktiv  && zu && ab) return 'aktivtausch';
  if (nurPassiv && zu && ab) return 'passivtausch';
  if (!nurAktiv && !nurPassiv && ab === 0) return 'bilanzverlaengerung';
  if (!nurAktiv && !nurPassiv && zu === 0) return 'bilanzverkuerzung';
  return null;
}

