const POOL_BRANCHEN = {neutral:'neutral', industrie:'Industrie', grosshandel:'Großhandel', mk:'Marketingkommunikation', bm:'Büromanagement', einzelhandel:'Einzelhandel'};
const POOL_ALLE_MODULE = POOL_QUELLEN.flatMap(q => POOL_MODULE_ROH[q.key].map(m => ({...m,
  id:q.key + '_' + m.id, quelle:q.key, quelleTitel:q.titel, fach:q.fach, branche:q.branche, kr:q.kr, nrQuelle:m.nr,
  voraussetzt:(m.voraussetzt || []).map(v => q.key + '_' + v)})));
(() => {   // Beschriftung aus dem Profil
  const t = PROFIL ? PROFIL.titel : 'Aufgabenpool', k = PROFIL ? (PROFIL.kennung || '') : 'alle Aufgaben';
  document.title = t + (typeof KENNUNG_TITEL !== 'undefined' && KENNUNG_TITEL ? ' · ' + KENNUNG_TITEL : '');
  const setz = () => { const h = document.getElementById('app-titel'), kk = document.getElementById('app-kennung');
    if (h) h.textContent = t; if (kk){ kk.textContent = k; kk.style.display = k ? '' : 'none'; } };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', setz); else setz();
})();
const MODULE = (() => {
  if (!PROFIL){ return POOL_ALLE_MODULE.map((m, i) => ({...m, nr:String(i + 1)})); }
  const nachId = {}; POOL_ALLE_MODULE.forEach(m => nachId[m.id] = m);
  const drin = new Set(), liste = [];
  PROFIL.felder.forEach(f => f.module.forEach(id => { if (nachId[id] && !drin.has(id)){ drin.add(id); liste.push(nachId[id]); } }));
  const anders = PROFIL.anders || {};   // je Trainer: andere Modulbezeichnung, Ziel oder Merksatz
  return liste.map((m, i) => ({...m, ...(anders[m.id] || {}), nr:String(i + 1), voraussetzt:m.voraussetzt.filter(v => drin.has(v))}));
})();
const modulFinden = id => MODULE.find(m => m.id === id);
const SCHWELLE = 3;   // so viele verschiedene Fälle je Modul auf Anhieb richtig = beherrscht

