const STANDARD_BANK = (() => {
  const vor = (k, x) => x && !String(x).startsWith(k + '_') ? k + '_' + x : x;
  const alle = POOL_QUELLEN.flatMap(q => window['POOL_BANK_' + q.key].map(a => Object.assign(a, {id:vor(q.key, a.id), modul:vor(q.key, a.modul || 'M5')})));
  if (!PROFIL) return alle;
  const drin = new Set(MODULE.map(m => m.id)), ohne = new Set(PROFIL.ohne || []);   // ohne: einzelne Aufgaben ausblenden
  const liste = alle.filter(a => drin.has(a.modul) && !ohne.has(a.id));
  // umbenennen: je Trainer Begriffe in Titeln und Schlagwörtern ersetzen, z. B. {Abiturfall:'Klausurfall'} in der WG-Eingangsklasse
  Object.entries(PROFIL.umbenennen || {}).forEach(([alt, neu]) => liste.forEach(a => {
    if (a.titel) a.titel = a.titel.split(alt).join(neu);
    if (a.tags) a.tags = a.tags.map(t => t === alt ? neu : t);
  }));
  return liste;
})();

/* ---------- Werte berechnen & Varianten erzeugen ---------- */
const runde = z => Math.round((Number(z)+Number.EPSILON)*100)/100;

function werteBerechnen(aufgabe, faktor){
  const f = faktor || 1;
  const w = {};
  Object.entries(aufgabe.werte || {}).forEach(([k,v]) => {
    w[k] = (k === 'satz') ? v : runde(v * f);
  });
  if (w.netto != null && w.satz != null){
    w.ust = runde(w.netto * w.satz);
    w.brutto = runde(w.netto + w.ust);
  }
  Object.entries(aufgabe.formeln || {}).forEach(([k, ausdruck]) => {
    w[k] = runde(rechne(ausdruck, w));
  });
  return w;
}

/* Sehr kleiner, abgesicherter Formelauswerter – nur Zahlen, Werte-Namen, + - * / ( ) */
function rechne(ausdruck, werte){
  if (!/^[A-Za-zÄÖÜäöü0-9_.\s+\-*/()]+$/.test(ausdruck)) return 0;
  const namen = Object.keys(werte);
  try {
    const fn = new Function(...namen, 'return (' + ausdruck + ');');
    const erg = fn(...namen.map(n => werte[n]));
    return Number.isFinite(erg) ? erg : 0;
  } catch(e){ return 0; }
}

const FAKTOREN = [0.5, 0.75, 1.25, 1.5, 2, 2.5, 3];

/* Erzeugt eine Aufgaben-Instanz: konkrete Beträge, ggf. mit verändertem Zahlenmaterial */
/* Antwortauswahl unter Tabellen fest mischen (05.11.2026, B11): In den Quellen steht die richtige Antwort meist zuerst.
   Startwert aus Kennung und Antworttexten → überall dieselbe Reihenfolge (Üben, Test, Druck, Auswertung); Felder mit
   denselben Antworten (Raster) bekommen dieselbe Reihenfolge. Nicht gemischt: Zuordnungen (z0, z1 … – Kategorien in fester
   Reihenfolge) und beschriftete Antworten („A: …“, „a) …“). */
function wahlFestMischen(felder, id){
  felder.forEach(f => {
    if (f.art !== 'wahl' || /^z\d+$/.test(f.id) || !f.optionen || f.optionen.length < 2) return;
    const T = f.optionen.map(o => String(o.text || '').replace(/<[^>]+>/g, '').trim());
    if (T.every(t => /^([A-Za-z]|\d+)\s*[:)\.]\s/.test(t))) return;
    let h = 2166136261; for (const ch of id + '|' + T.join('|')) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
    const z = () => { h = (h + 0x6D2B79F5) >>> 0; let t = h; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
    const o = f.optionen.slice(); for (let i = o.length - 1; i > 0; i--){ const j = Math.floor(z() * (i + 1)); [o[i], o[j]] = [o[j], o[i]]; }
    f.optionen = o;
  });
  return felder;
}
function instanzBauen(aufgabe, variieren){
  let faktor = 1;
  if (variieren && aufgabe.werte && Object.keys(aufgabe.werte).length){
    faktor = FAKTOREN[Math.floor(Math.random()*FAKTOREN.length)];
  }
  let w = werteBerechnen(aufgabe, faktor);
  let zeilen = zeilenBauen(aufgabe, w);
  const buchung = (aufgabe.typ || 'buchungssatz') === 'buchungssatz';
  // Sicherheitsnetz: Variante nur übernehmen, wenn der Satz ausgeglichen und centgenau bleibt
  if (buchung && (!istAusgeglichen(zeilen) || zeilen.some(z => Math.abs(z.betrag*100 - Math.round(z.betrag*100)) > 1e-6))){
    w = werteBerechnen(aufgabe, 1);
    zeilen = zeilenBauen(aufgabe, w);
    faktor = 1;
  }
  const inst = {
    quelle: aufgabe,
    id: aufgabe.id,
    typ: aufgabe.typ || 'buchungssatz',
    modul: aufgabe.modul || 'M5',
    gruppe: aufgabe.gruppe || null,
    titel: aufgabe.titel || 'Aufgabe',
    stufe: aufgabe.stufe ?? 2,
    tags: aufgabe.tags || [],
    text: platzhalter(aufgabe.text || '', w),
    hinweise: (aufgabe.hinweise || []).map(h => platzhalter(h, w)),
    merke: aufgabe.merke ? platzhalter(aufgabe.merke, w) : '',
    stolpersteine: aufgabe.stolpersteine || [],
    werte: w,
    variante: faktor !== 1,
    vorgabe: aufgabe.vorgabe || null,
    muster: zeilen
  };
  if (inst.typ === 'tabelle'){
    inst.tabelle = JSON.parse(JSON.stringify(aufgabe.tabelle || {spalten:[], zeilen:[]}));
    inst.felder = JSON.parse(JSON.stringify(aufgabe.felder || []));
    inst.rechenweg = aufgabe.rechenweg || '';
    wahlFestMischen(inst.felder, aufgabe.id);
    if (aufgabe.pz != null) inst.pz = aufgabe.pz;
    inst.faktor = 1; inst.variante = false; inst.muster = [];
  }
  if (inst.typ === 'anschaffungskosten'){
    inst.posten = mischen((aufgabe.posten || []).map(p => ({label:p.label, wert:runde(p.wert), anzeige:p.anzeige != null ? runde(p.anzeige) : null, dazu:!!p.dazu, grund:p.grund || ''})));
    inst.variante = false;
    inst.muster = inst.posten;
  }
  if (inst.typ === 'kette'){
    inst.bloecke = (aufgabe.bloecke || []).map(b => b.typ === 'rechnen'
      ? {id:b.id, titel:b.titel, typ:'rechnen', frage:b.frage, antwort:runde(b.antwort), tipp:b.tipp || '', rechenweg:b.rechenweg || '', einheit:b.einheit || '€', nachkomma:b.nachkomma, formel:b.formel || null, richtung:b.richtung || null, alternativen:(b.alternativen || []).map(runde)}
      : {id:b.id, titel:b.titel, optional:!!b.optional,
         muster: b.muster.map(z => ({seite:z.seite, konto:String(z.konto).trim(), betrag:runde(z.betrag), formel:z.formel || null})),
         muster2: b.muster2 ? b.muster2.map(z => ({seite:z.seite, konto:String(z.konto).trim(), betrag:runde(z.betrag)})) : null});
    inst.variante = false;
    inst.muster = inst.bloecke;
  }
  if (inst.typ === 'wareneinsatz'){
    inst.posten = (aufgabe.posten || []).map(p => ({label:p.label, wert:runde(p.wert), ziel:p.ziel || null, grund:p.grund || ''}));
    inst.posten = mischen([...inst.posten]);
    inst.umsatz = {label: aufgabe.umsatz.label, wert: runde(aufgabe.umsatz.wert)};
    inst.variante = false;
    inst.muster = inst.posten;
  }
  if (inst.typ === 'labor'){ inst.labor = aufgabe.labor; inst.laborVariante = aufgabe.laborVariante || ''; inst.variante = false; inst.muster = []; }
  if (inst.typ === 'berechnung'){
    inst.frage = aufgabe.frage || '';
    // Optionen sind entweder Beträge (wert) oder Textantworten (text) – z. B. bei reinen Theoriefragen.
    inst.optionen = mischen((aufgabe.optionen || []).map(o => ({
      wert: o.text ? null : runde(o.wert), text: o.text || null,
      richtig: !!o.richtig, weg: o.weg || '', fehler: o.fehler || ''
    })));
    inst.mehrfach = !!aufgabe.mehrfach;
    inst.variante = false;
    inst.muster = inst.optionen;
  }
  if (inst.typ === 'herstellungskosten'){
    const skala = variieren ? FAKTOREN[Math.floor(Math.random()*FAKTOREN.length)] : 1;
    let posten = (aufgabe.posten || []).map(x => ({
      name:x.name, betrag:runde((x.betrag || 0) * skala), gruppe:x.gruppe, grund:x.grund || ''
    }));
    if (variieren) posten = mischen(posten);
    inst.posten = posten;
    inst.variante = !!variieren;
    inst.muster = posten;
  }
  if (inst.typ === 'bilanzaufstellung'){
    const skala = variieren ? FAKTOREN[Math.floor(Math.random()*FAKTOREN.length)] : 1;
    let posten = (aufgabe.posten || []).map(x => ({
      name:x.name, betrag:runde((x.betrag || 0) * skala), gruppe:x.gruppe, rang:x.rang || 0
    }));
    inst.reihenfolge = !!aufgabe.reihenfolge;
    if (variieren) posten = mischen(posten);
    inst.posten = posten;
    inst.bilanzTitel = aufgabe.bilanzTitel || 'Bilanz';
    inst.variante = !!variieren;
    inst.muster = posten;
  }
  if (inst.typ === 'kontenabschluss'){
    inst.konten = aufgabe.konten
      ? aufgabe.konten.map(k => ({konto:String(k.konto).trim(), anfangsbestand:runde(k.anfangsbestand || 0), label:k.label}))
      : [{konto:String(aufgabe.konto).trim(), anfangsbestand:runde(aufgabe.anfangsbestand || 0), label:aufgabe.label}];
    const erst = inst.konten[0].konto;
    const liste = (aufgabe.faelle || []).map(x => ({
      text:x.text, betrag:runde(x.betrag || 0),
      konto: x.seite ? String(x.konto || erst).trim() : null,
      seite: x.seite || null, grund:x.grund || ''
    }));
    inst.faelle = variieren ? mischen([...liste]) : liste;
    inst.variante = !!variieren;
    inst.betraegeSelbst = aufgabe.betraegeSelbst === true;
    inst.muster = inst.faelle;
    if (!aufgabe.text){
      const mehr = inst.konten.length > 1;
      inst.text = `Buche die folgenden Geschäftsvorfälle auf ${mehr ? 'den T-Konten' : 'dem T-Konto'}. `
        + `${mehr ? 'Die Anfangsbestände sind' : 'Der Anfangsbestand ist'} vorgegeben. `
        + `Entscheide bei jedem Fall${mehr ? ', welches Konto betroffen ist und' : ','} auf welcher Seite gebucht wird; `
        + `die Beträge werden übernommen. Ermittle zum Schluss den Schlussbestand.`;
    }
  }
  if (inst.typ === 'bilanzwirkung'){
    inst.positionen = (aufgabe.positionen || []).map(pos => ({
      name: pos.name,
      richtung: pos.richtung,
      betrag: pos.betrag != null ? runde(pos.betrag) : runde(w[pos.wert] || 0)
    }));
    inst.vorgangsart = aufgabe.vorgangsart || vorgangsartAbleiten(inst.positionen);
    inst.muster = inst.positionen;
  }
  return inst;
}

function zeilenBauen(aufgabe, w){
  const raus = [];
  ['soll','haben'].forEach(seite => {
    (aufgabe[seite] || []).forEach(z => {
      const betrag = (z.betrag != null && z.betrag !== '')
        ? runde(parseFloat(z.betrag))
        : runde(w[z.wert] != null ? w[z.wert] : 0);
      if (String(z.konto||'').trim() === '') return;
      raus.push({seite, konto:String(z.konto).trim(), betrag});
    });
  });
  return raus;
}

const istAusgeglichen = z =>
  Math.abs(z.filter(x=>x.seite==='soll').reduce((s,x)=>s+x.betrag,0)
         - z.filter(x=>x.seite==='haben').reduce((s,x)=>s+x.betrag,0)) < 0.005;

function platzhalter(text, w){
  return String(text).replace(/\{(\w+)\}/g, (treffer, key) =>
    w[key] != null ? euro(w[key]) : treffer);
}

const euro = z => Number(z).toLocaleString('de-DE',{minimumFractionDigits:2, maximumFractionDigits:2}) + ' €';
const zahl  = z => Number(z).toLocaleString('de-DE',{minimumFractionDigits:2, maximumFractionDigits:2});

function betragLesen(roh){
  if (roh == null) return null;
  // Rechenweg statt Betrag (z. B. 1800*19% oder 2142/1,19) – wie in den Tabellen
  if (typeof tabIstAusdruck === 'function' && tabIstAusdruck(roh)){ const v = tabZahl(roh); return v == null ? null : runde(v); }
  let s = String(roh).trim().replace(/[€%\s]/g,'');
  if (s === '') return null;
  if (s.includes(',')) s = s.replace(/\./g,'').replace(',','.');
  else if (/^-?\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g,'');
  const z = parseFloat(s);
  return Number.isFinite(z) ? runde(z) : null;
}

/* ==========================================================================
   3 · DIAGNOSTISCHE FEHLER-ENGINE
   ========================================================================== */
const FEHLERTYPEN = {
  seite:        'Soll und Haben vertauscht',
  kontenklasse: 'Falsche Kontenklasse',
  konto:        'Falsches Konto',
  steuer:       'Vorsteuer / Umsatzsteuer',
  brutto_netto: 'Brutto und Netto verwechselt',
  betrag:       'Rechenfehler im Betrag',
  fehlt:        'Buchungszeile fehlt',
  ueberfluessig:'Buchungszeile zu viel',
  ungleich:     'Soll- und Habenseite stimmen nicht überein',
  position:     'Falsche Bilanzposition',
  richtung:     'Zunahme und Abnahme vertauscht',
  vorgangsart:  'Art der Bilanzveränderung',
  inkonsistenz: 'Angaben widersprechen sich',
  betroffen:    'Konto betroffen oder nicht',
  kontoWahl:    'Falsches Konto gewählt',
  gliederung:   'Gliederung der Bilanz',
  hk_zuordnung: 'Bestandteile der Herstellungskosten',
  hk_offen:     'Position nicht zugeordnet',
  rechnung:     'Berechnung',
  ablenker:     'Ablenkerwert erkannt',
  wareneinsatz: 'Wareneinsatz',
  rohgewinn:    'Warenrohgewinn',
  summe:        'Summe der Anschaffungskosten',
  reihenfolge_satz: 'Reihenfolge im Buchungssatz',
  bilanzseite:  'Aktiv- oder Passivseite',
  eigenkapital: 'Eigenkapital',
  saldo:        'Schlussbestand'
};

const gleichBetrag = (a,b) => Math.abs(a-b) < 0.005;
const gegen = s => s === 'soll' ? 'haben' : 'soll';
const seiteLang = s => s === 'soll' ? 'Soll' : 'Haben';

/* Im Buchungssatz stehen alle Soll-Zeilen vor allen Haben-Zeilen.
   Geprüft wird nur, ob nach der letzten Haben-Zeile keine Soll-Zeile mehr folgt. */
function reihenfolgeOk(eingabe){
  let sahHaben = false;
  for (const z of eingabe){
    if (z.seite === 'haben') sahHaben = true;
    else if (z.seite === 'soll' && sahHaben) return false;
  }
  return true;
}

function diagnose(muster, eingabe, werte, reihenfolgePruefen){
  const m = muster.map((z,i) => ({...z, i, offen:true}));
  const e = eingabe.map((z,i) => ({...z, i, offen:true}));
  const paare = [];

  const zuordnen = (pruef, status) => {
    m.forEach(mz => {
      if (!mz.offen) return;
      const treffer = e.find(ez => ez.offen && pruef(mz, ez));
      if (treffer){ mz.offen = false; treffer.offen = false; paare.push({muster:mz, eingabe:treffer, status}); }
    });
  };

  zuordnen((a,b) => a.seite===b.seite && a.konto===b.konto && gleichBetrag(a.betrag,b.betrag), 'ok');
  zuordnen((a,b) => a.seite===b.seite && a.konto===b.konto, 'betrag');
  zuordnen((a,b) => a.seite!==b.seite && a.konto===b.konto, 'seite');
  zuordnen((a,b) => a.seite===b.seite && gleichBetrag(a.betrag,b.betrag), 'konto');
  zuordnen((a,b) => a.seite!==b.seite && gleichBetrag(a.betrag,b.betrag), 'seite_konto');
  zuordnen((a,b) => a.seite===b.seite, 'konto');

  m.filter(z => z.offen).forEach(mz => paare.push({muster:mz, eingabe:null, status:'fehlt'}));
  e.filter(z => z.offen).forEach(ez => paare.push({muster:null, eingabe:ez, status:'ueberfluessig'}));

  paare.sort((a,b) => {
    const s = z => z.muster ? (z.muster.seite==='soll'?0:1)*100 + z.muster.i : 900 + (z.eingabe?z.eingabe.i:0);
    return s(a) - s(b);
  });

  const inhaltOk = paare.every(p => p.status === 'ok');
  // Die Reihenfolge wird nur gemeldet, wenn Konten, Seiten und Beträge bereits stimmen –
  // sonst würde ein formaler Hinweis den eigentlichen Fehler überdecken.
  const reihenfolgeVerletzt = !!reihenfolgePruefen && inhaltOk && !reihenfolgeOk(eingabe);
  const korrekt = inhaltOk && !reihenfolgeVerletzt;
  const befunde = reihenfolgeVerletzt
    ? [{typ:'reihenfolge_satz', stufe:'rot', titel:'Erst alle Soll-, dann alle Haben-Zeilen',
        text:'Konten, Seiten und Beträge stimmen. Im Buchungssatz stehen aber zuerst sämtliche Soll-Zeilen und erst danach die Haben-Zeilen – bei dir folgt noch eine Soll-Zeile auf eine Haben-Zeile.'}]
    : (korrekt ? [] : befundeBauen(paare, muster, eingabe, werte || {}));
  const typen = [...new Set(befunde.map(b => b.typ))];
  return {korrekt, paare, befunde, typen, hauptfehler: typen[0] || null};
}

function befundeBauen(paare, muster, eingabe, werte){
  const b = [];
  const satz = werte.satz || 0.19;
  const summeS = eingabe.filter(z=>z.seite==='soll').reduce((s,z)=>s+z.betrag,0);
  const summeH = eingabe.filter(z=>z.seite==='haben').reduce((s,z)=>s+z.betrag,0);

  /* --- Grundregel: Summengleichheit --- */
  if (eingabe.length && !gleichBetrag(summeS, summeH)){
    b.push({
      typ:'ungleich', stufe:'rot', titel:'Der Buchungssatz ist nicht ausgeglichen',
      text:`Soll ${euro(summeS)} gegen Haben ${euro(summeH)} – eine Differenz von <span class="k">${euro(Math.abs(summeS-summeH))}</span>. Jeder Buchungssatz muss auf beiden Seiten dieselbe Summe ergeben. Prüfe zuerst, ob ein Betrag falsch berechnet oder eine Zeile vergessen wurde.`
    });
  }

  /* --- Kombinationsbefund: brutto gebucht + Steuerzeile vergessen --- */
  const steuerFehlt = paare.find(p => p.status==='fehlt' && istSteuerkonto(p.muster.konto));
  const bruttoStattNetto = paare.find(p => p.status==='betrag' && p.eingabe &&
      gleichBetrag(p.eingabe.betrag, runde(p.muster.betrag*(1+satz))));
  if (steuerFehlt && bruttoStattNetto){
    const st = steuerFehlt.muster.konto;
    b.push({
      typ:'steuer', stufe:'rot', titel:'Bruttobetrag gebucht und Steuerzeile vergessen',
      text:`Auf <span class="k">${kVoll(bruttoStattNetto.muster.konto)}</span> steht der Bruttobetrag ${euro(bruttoStattNetto.eingabe.betrag)}. Dort gehört der Nettowert ${euro(bruttoStattNetto.muster.betrag)} hin – die Differenz von ${euro(runde(bruttoStattNetto.eingabe.betrag - bruttoStattNetto.muster.betrag))} ist ${st===STEUERKONTEN[0]?'Vorsteuer':'Umsatzsteuer'} und braucht eine eigene Zeile auf <span class="k">${kVoll(st)}</span>, hier im <b>${seiteLang(steuerFehlt.muster.seite)}</b>. ${steuerSeitenSatz(st, steuerFehlt.muster.seite)}`,
      schau: miniTKonto(st)
    });
  }

  paare.forEach(p => {
    /* ---------- Richtige Konten, falsche Seite ---------- */
    if (p.status === 'seite'){
      const k = p.muster.konto, art = kontoArt(k);
      const bewegung = p.muster.seite === MEHRUNG[art] ? 'Zugang bzw. Mehrung' : 'Abgang bzw. Minderung';
      b.push({
        typ:'seite', stufe:'rot',
        titel:`${k} auf der falschen Seite gebucht`,
        text:`<span class="k">${kVoll(k)}</span> ist ein ${ART_NAME[art]}. Hier liegt ein <b>${bewegung}</b> vor, deshalb gehört der Betrag ins <b>${seiteLang(p.muster.seite)}</b> – du hast im ${seiteLang(p.eingabe.seite)} gebucht. ${artRegel(k)}`,
        schau: miniTKonto(k)
      });
    }

    /* ---------- Falsches Konto ---------- */
    if (p.status === 'konto' || p.status === 'seite_konto'){
      const soll_k = p.muster.konto, ist_k = p.eingabe.konto;
      const artM = kontoArt(soll_k), artE = kontoArt(ist_k);
      const hinweisText = verwechslungsText(soll_k, ist_k);
      const beideSteuer = istSteuerkonto(soll_k) && istSteuerkonto(ist_k);
      let typ = 'konto', titel = 'Falsches Konto gewählt';
      if (beideSteuer){ typ='steuer'; titel='Vorsteuer und Umsatzsteuer verwechselt'; }
      else if (artM !== artE){ typ='kontenklasse'; titel=`${ART_NAME[artE]} statt ${ART_NAME[artM]}`; }
      else if (hinweisText){ typ='kontenklasse'; }
      let text = `Gebucht: <span class="k rotstift">${kVoll(ist_k)}</span>. Erwartet: <span class="k">${kVoll(soll_k)}</span>.`;
      if (artM !== artE) text += ` <span class="k">${ist_k}</span> ist ein ${ART_NAME[artE]}, gefragt ist ein ${ART_NAME[artM]}.`;
      if (hinweisText) text += ' ' + hinweisText;
      else text += ' ' + artRegel(soll_k);
      if (p.status === 'seite_konto') text += ` Zusätzlich steht die Zeile auf der falschen Seite: richtig ist ${seiteLang(p.muster.seite)}.`;
      b.push({typ, stufe:'rot', titel, text, schau: miniTKonto(soll_k)});
    }

    /* ---------- Richtiges Konto, falscher Betrag ---------- */
    if (p.status === 'betrag'){
      if (bruttoStattNetto && steuerFehlt && p === bruttoStattNetto) return; // schon oben erklärt
      const ist = p.eingabe.betrag, sollB = p.muster.betrag;
      const k = p.muster.konto;
      const q = sollB !== 0 ? ist/sollB : 0;
      const steuerImSatz = muster.some(z => istSteuerkonto(z.konto));
      if (istSteuerkonto(k) && gleichBetrag(ist, runde(sollB*(1+satz)))){
        b.push({typ:'steuer', stufe:'rot', titel:'Steuer von der falschen Bemessungsgrundlage berechnet',
          text:`Auf <span class="k">${kVoll(k)}</span> stehen ${euro(ist)}. Das entspricht ${Math.round(satz*100)} % vom <b>Bruttobetrag</b>. Die Steuer bemisst sich aber vom Nettobetrag: richtig sind ${euro(sollB)}. Aus einem Bruttobetrag rechnest du die Steuer mit dem Faktor ${zahl(satz/(1+satz)*100)} % heraus – oder du teilst durch ${zahl(1+satz)}.`});
      } else if (istSteuerkonto(k)){
        b.push({typ:'steuer', stufe:'rot', titel:`Steuerbetrag auf ${k} stimmt nicht`,
          text:`Gebucht: <span class="rotstift">${euro(ist)}</span>, erwartet: <span class="k">${euro(sollB)}</span>. Rechne ${Math.round(satz*100)} % vom maßgeblichen Nettobetrag und prüfe, worauf sich die Steuer bemisst.`});
      } else if (gleichBetrag(ist, runde(sollB*(1+satz)))){
        b.push({typ:'brutto_netto', stufe:'rot', titel:`Bruttobetrag statt Nettobetrag auf ${k}`,
          text:`Auf <span class="k">${kVoll(k)}</span> stehen ${euro(ist)}. Das ist der um ${Math.round(satz*100)} % erhöhte Betrag. Richtig sind ${euro(sollB)}. `
            + (steuerImSatz
               ? `Die Differenz von ${euro(runde(ist-sollB))} ist Steuer und bekommt eine eigene Zeile.`
               : 'Bei diesem Vorgang fällt gar keine Umsatzsteuer an – die Steuer wurde bereits beim Rechnungseingang gebucht.')});
      } else if (gleichBetrag(ist, runde(sollB/(1+satz)))){
        b.push({typ:'brutto_netto', stufe:'rot', titel:`Nettobetrag statt Bruttobetrag auf ${k}`,
          text:`Auf <span class="k">${kVoll(k)}</span> gehört der Bruttobetrag ${euro(sollB)}, denn dieses Konto trägt den vollen Rechnungsbetrag inklusive Steuer. Du hast ${euro(ist)} gebucht – das ist der Nettowert.`});
      } else {
        const diff = runde(ist - sollB);
        const passt = muster.find(z => z.konto !== k && gleichBetrag(Math.abs(diff), z.betrag));
        b.push({typ:'betrag', stufe:'rot', titel:`Betrag auf ${k} stimmt nicht`,
          text:`Gebucht: <span class="rotstift">${euro(ist)}</span>, erwartet: <span class="k">${euro(sollB)}</span> – Abweichung ${euro(Math.abs(diff))}.`
            + (passt ? ` Genau dieser Betrag taucht im Buchungssatz auf <span class="k">${kVoll(passt.konto)}</span> auf. Prüfe, ob du ihn versehentlich abgezogen oder hinzugerechnet hast.` : '')
            + (Math.abs(q-2)<0.01 ? ' Der Betrag ist genau doppelt so hoch.' : '')});
      }
    }

    /* ---------- Fehlende Zeile ---------- */
    if (p.status === 'fehlt'){
      if (steuerFehlt && bruttoStattNetto && p === steuerFehlt) return;
      const k = p.muster.konto;
      if (istSteuerkonto(k)){
        b.push({typ:'steuer', stufe:'rot', titel:`${kName(k)} fehlt`,
          text:`Es fehlt die Zeile <span class="k">${kVoll(k)}</span> über ${euro(p.muster.betrag)} im ${seiteLang(p.muster.seite)}. ${steuerSeitenSatz(k, p.muster.seite)}`,
          schau: miniTKonto(k)});
      } else {
        b.push({typ:'fehlt', stufe:'gelb', titel:`Eine Buchungszeile fehlt`,
          text:`Im ${seiteLang(p.muster.seite)} fehlt <span class="k">${kVoll(k)}</span> über ${euro(p.muster.betrag)}. Bei zusammengesetzten Buchungssätzen stehen auf einer Seite mehrere Konten – hier ist noch nicht jeder betroffene Sachverhalt erfasst.`});
      }
    }

    /* ---------- Überflüssige Zeile ---------- */
    if (p.status === 'ueberfluessig'){
      const k = p.eingabe.konto;
      b.push({typ:'ueberfluessig', stufe:'gelb', titel:`${k} gehört nicht in diesen Buchungssatz`,
        text:`<span class="k rotstift">${kVoll(k)}</span> über ${euro(p.eingabe.betrag)} im ${seiteLang(p.eingabe.seite)} ist im Musterbuchungssatz nicht vorgesehen. Frage dich: Welcher Vermögens- oder Schuldposten verändert sich durch diesen Vorgang tatsächlich?`});
    }
  });

  /* Reihenfolge: Grundregel, Seite, Steuer, Konto, Rest */
  const rang = {ungleich:0, seite:1, steuer:2, brutto_netto:3, kontenklasse:4, konto:5, betrag:6, fehlt:7, ueberfluessig:8};
  b.sort((x,y) => rang[x.typ] - rang[y.typ]);
  return b;
}

/* Erklärt, warum die Steuerzeile auf dieser Seite steht */
function steuerSeitenSatz(konto, seite){
  const normal = MEHRUNG[kontoArt(konto)];
  if (seite === normal){
    return konto === STEUERKONTEN[0]
      ? 'Vorsteuer ist eine Forderung an das Finanzamt und wird beim Rechnungseingang im Soll gebucht.'
      : 'Umsatzsteuer ist eine Schuld gegenüber dem Finanzamt und wird beim Verkauf im Haben gebucht.';
  }
  return 'Hier wird eine bereits gebuchte Steuer nachträglich korrigiert – deshalb steht die Zeile auf der Gegenseite.';
}

/* Mini-T-Konto als Schaubild zur Buchungsseite */
function miniTKonto(konto){
  const art = kontoArt(konto);
  const mehrungLinks = MEHRUNG[art] === 'soll';
  const paare = {
    aktiv:   ['Zugang / Mehrung','Abgang / Minderung'],
    passiv:  ['Abgang / Minderung','Zugang / Mehrung'],
    aufwand: ['Aufwand entsteht','Korrektur / Abschluss'],
    ertrag:  ['Korrektur / Abschluss','Ertrag entsteht'],
    abschluss:['Soll','Haben']
  }[art];
  const linksPlus = mehrungLinks;
  return `<div class="schau"><div class="mini-t">
    <div class="kopfz">${kVoll(konto)} · ${ART_NAME[art]}</div>
    <div class="body">
      <div class="zelle ${linksPlus?'plus-z':'minus-z'}"><span class="lbl">Soll</span>${paare[0]}</div>
      <div class="mitte"></div>
      <div class="zelle ${linksPlus?'minus-z':'plus-z'}"><span class="lbl">Haben</span>${paare[1]}</div>
    </div>
  </div></div>`;
}

/* ==========================================================================
   4 · LERNSTAND, LEITNER-WIEDERVORLAGE, ADAPTIVE STEUERUNG
   ========================================================================== */
const SPEICHER_KEY = SP + '.lernstand.v3';
const BANK_KEY     = SP + '.aufgabenbank.v3';
let speicherAktiv = true;

function leseSpeicher(key){
  try { const r = localStorage.getItem(key); return r ? JSON.parse(r) : null; }
  catch(e){ speicherAktiv = false; return null; }
}
function schreibeSpeicher(key, wert){
  try { localStorage.setItem(key, JSON.stringify(wert)); }
  catch(e){ speicherAktiv = false; }
}

const LEER_STAND = {
  version:1, zaehler:0, niveau:1, modulStand:{}, modulWahl:null, gruppenWahl:null, letztesModul:null, letzterFallModul:null, vorschau:false, seitWdh:0, modus:'frei',
  gesamt:{versuche:0, geloest:0, ohneFehler:0, streak:0},
  tags:{}, fehler:{}, letzteFehler:[], leitner:{}, gesehen:[], verlauf:[], drills:0, fehlerheft:{}
};

let S = Object.assign(JSON.parse(JSON.stringify(LEER_STAND)), leseSpeicher(SPEICHER_KEY) || {});
const ENTFERNTE_AUFGABEN = new Set(["K9"]);
let BANK = (() => {
  const gespeichert = leseSpeicher(BANK_KEY);
  if (!Array.isArray(gespeichert)) return STANDARD_BANK;
  const std = new Set(STANDARD_BANK.map(a => a.id));
  return STANDARD_BANK.concat(gespeichert.filter(a => a && !std.has(a.id) && !ENTFERNTE_AUFGABEN.has(a.id)));
})();

/* Kurzübersicht für die Startseite (index.html): liest nur diese kleine Zusammenfassung */
function uebersichtSchreiben(){
  const ids = new Set(BANK.map(a => a.id)), sichtbar = MODULE.filter(m => !m.ausgeblendet && m.verfuegbar && modulAufgaben(m.id).length);
  const gesehen = new Set([...(S.gesehen || []), ...(S.verlauf || []).map(e => e.id)].filter(x => ids.has(x)));
  schreibeSpeicher(SPEICHER_KEY.replace(/lernstand\.v3$/, 'uebersicht'), {v:1, aufgaben:BANK.length, bearbeitet:gesehen.size,
    geloest:S.gesamt.geloest || 0, ohneFehler:S.gesamt.ohneFehler || 0, serie:S.gesamt.streak || 0,
    module:sichtbar.length, beherrscht:sichtbar.filter(m => modulBeherrscht(m.id)).length,
    zuletzt:(S.verlauf && S.verlauf[0] && S.verlauf[0].zeit) || null, letztesModul:(sichtbar.find(m => m.id === S.letztesModul) || {}).titel || null});
}
const standSpeichern = () => { schreibeSpeicher(SPEICHER_KEY, S); try { uebersichtSchreiben(); } catch(e){} };
setTimeout(() => { try { uebersichtSchreiben(); } catch(e){} }, 0);
const bankSpeichern  = () => schreibeSpeicher(BANK_KEY, BANK);

function tagStand(tag){
  if (!S.tags[tag]) S.tags[tag] = {versuche:0, ohneFehler:0, fehler:0, streak:0};
  return S.tags[tag];
}

/* ---------- Modulfortschritt ---------- */
function modulAufgaben(id){ return BANK.filter(a => (a.modul || 'M5') === id); }
function modulStand(id){
  if (!S.modulStand) S.modulStand = {};
  if (!S.modulStand[id]) S.modulStand[id] = {geloest:[], versuche:0};
  return S.modulStand[id];
}
function modulKern(id){ return modulAufgaben(id).filter(a => !a.vorgabe && a.typ !== 'labor'); }   // alle Aufgaben zählen (auch Multiple Choice), sonst passen Häkchen und Zähler nicht zusammen
function modulSchwelle(id){ return Math.min(SCHWELLE, modulKern(id).length || SCHWELLE); }
function modulBeherrscht(id){
  const kern = modulKern(id).map(a => a.id);
  if (!kern.length) return false;
  const geloest = modulStand(id).geloest.filter(x => kern.includes(x));
  return geloest.length >= modulSchwelle(id);
}
/* Die echte Regel – für den Lernweg und die Anzeige im Lernstand */
function modulFreiEcht(id){
  const m = modulFinden(id);
  if (!m || m.ausgeblendet || !m.verfuegbar || !modulAufgaben(id).length) return false;
  return (m.voraussetzt || []).every(v => modulBeherrscht(v));
}
/* Im Vorschaumodus sind alle vorhandenen Module zugänglich */
function modulFrei(id){
  const m = modulFinden(id);
  if (!m || m.ausgeblendet || !m.verfuegbar || !modulAufgaben(id).length) return false;
  return (S.vorschau || !imLernpfad()) ? true : modulFreiEcht(id);
}
function imLernpfad(){ return false; }   // Lernpfad entfernt (11.10.2026) – es gibt nur noch freies Üben
/* Freies Üben: der Reihe nach durch das gewählte Modul */
function freieAufgabe(frei){
  let id = (S.modulWahl && modulFrei(S.modulWahl)) ? S.modulWahl : (S.letztesModul && modulFrei(S.letztesModul) ? S.letztesModul : frei[0]);
  S.modulWahl = id; S.letztesModul = id;
  const liste = blaetterListe();
  if (!liste.length) return null;
  let i = aktuell && aktuell.modul === id ? liste.findIndex(a => a.id === aktuell.id) : -1;
  i = (i + 1) % liste.length; blaetterIndex = i;
  return instanzBauen(liste[i], false);
}
/* Beherrscht heißt: das nächste Modul ist freigeschaltet.
   Es heißt nicht, dass das laufende Modul schon abgearbeitet ist – erst wenn
   jeder Fall einmal dran war, zieht der Tutor weiter. */
function modulHatNeues(id){ return modulAufgaben(id).some(a => !S.gesehen.includes(a.id)); }
function aktivesModul(){
  if (S.modulWahl && modulFrei(S.modulWahl)) return S.modulWahl;
  const frei = MODULE.filter(m => modulFrei(m.id));
  const mitNeuem = frei.find(m => modulHatNeues(m.id));
  if (mitNeuem) return mitNeuem.id;
  const offen = frei.find(m => !modulBeherrscht(m.id));
  return offen ? offen.id : (frei.length ? frei[frei.length-1].id : null);
}

/* ---------- Auswahl der nächsten Aufgabe ---------- */
function naechsteAufgabe(){
  const frei = MODULE.filter(m => modulFrei(m.id)).map(m => m.id);
  if (!frei.length) return null;
  if (!imLernpfad()) return freieAufgabe(frei);
  // Ist ein Modul festgehalten, gilt das auch für die Wiedervorlage
  const erlaubt = (S.modulWahl && modulFrei(S.modulWahl)) ? [S.modulWahl] : frei;

  // 1 · Fällige Wiederholung – aber nie zwei Wiederholungen hintereinander
  const faellig = BANK.filter(a => erlaubt.includes(a.modul || 'M5')
      && S.leitner[a.id] && S.leitner[a.id].faellig <= S.zaehler);
  // Höchstens jede dritte Aufgabe ist eine Wiederholung – neues Material soll überwiegen
  S.seitWdh = (S.seitWdh || 0) + 1;
  if (faellig.length && S.seitWdh >= 3){
    S.seitWdh = 0;
    faellig.sort((a,b) => S.leitner[a.id].box - S.leitner[b.id].box);
    return instanzBauen(faellig[0], true);
  }

  // 2 · Aufgabe aus dem aktiven Modul, leichteste zuerst
  const ziel = aktivesModul();
  let kandidaten = modulAufgaben(ziel);
  if (S.modulWahl === ziel && S.gruppenWahl){
    const eng = kandidaten.filter(a => a.gruppe === S.gruppenWahl);
    if (eng.length) kandidaten = eng;
  }
  const neu = kandidaten.filter(a => !S.gesehen.includes(a.id));
  if (neu.length){
    // Erst wenn keine Aufgabe der niedrigsten Stufe mehr offen ist, geht es eine Stufe höher
    const stufe = Math.min(...neu.map(a => a.stufe ?? 2));
    const gruppe = neu.filter(a => (a.stufe ?? 2) === stufe);
    return instanzBauen(schwachstenZuerst(gruppe), false);
  }

  // 3 · Modul durchlaufen: die am wenigsten sichere Aufgabe, variiert
  const sortiert = [...kandidaten].sort((a,b) =>
    ((S.leitner[a.id]||{box:1}).box - (S.leitner[b.id]||{box:1}).box));
  return sortiert.length ? instanzBauen(sortiert[0], true) : null;
}

/* bevorzugt Aufgaben aus Themenfeldern mit der schlechtesten Quote */
function schwachstenZuerst(liste){
  const punkte = a => (a.tags||[]).reduce((p,t) => {
    const st = S.tags[t];
    if (!st || !st.versuche) return p + 0.5;
    return p + (1 - st.ohneFehler/st.versuche);
  }, 0) / Math.max(1,(a.tags||[]).length);
  return [...liste].sort((a,b) => punkte(b) - punkte(a))[0];
}

/* ---------- Ergebnis verbuchen ---------- */
function ergebnisVerbuchen(aufgabe, ergebnis, versuche){
  const ohneFehler = ergebnis.korrekt && versuche === 1;
  S.zaehler++;
  S.gesamt.geloest++;
  if (ohneFehler){ S.gesamt.ohneFehler++; S.gesamt.streak++; }
  else S.gesamt.streak = 0;

  if (!S.gesehen.includes(aufgabe.id)) S.gesehen.push(aufgabe.id);

  const ms = modulStand(aufgabe.modul || 'M5');
  ms.versuche++;
  // Medaillen: Wer eine Aufgabe nicht fehlerfrei gelöst hat, kann sie später noch einmal fehlerfrei lösen –
  // es zählt aber erst, wenn mindestens 3 andere Aufgaben dazwischen lagen (nicht gleich nach der Musterlösung).
  if (!S.fehlZeit) S.fehlZeit = {};
  const medVor = medaille(aufgabe.modul || 'M5');
  const zuFrueh = ohneFehler && S.fehlZeit[aufgabe.id] != null && S.zaehler - S.fehlZeit[aufgabe.id] <= 3;
  if (ohneFehler && !zuFrueh){ if (!ms.geloest.includes(aufgabe.id)) ms.geloest.push(aufgabe.id); delete S.fehlZeit[aufgabe.id]; }
  else if (!ohneFehler && !ms.geloest.includes(aufgabe.id)) S.fehlZeit[aufgabe.id] = S.zaehler;
  medailleMelden(aufgabe.modul || 'M5', medVor, zuFrueh && !ms.geloest.includes(aufgabe.id));
  fehlerheftBuchen(aufgabe, ohneFehler, zuFrueh);

  (aufgabe.tags||[]).forEach(t => {
    const st = tagStand(t);
    st.versuche++;
    if (ohneFehler){ st.ohneFehler++; st.streak++; }
    else { st.fehler++; st.streak = 0; }
  });

  // Sicherheitsstufe fortschreiben
  const l = S.leitner[aufgabe.id] || {box:1};
  if (ohneFehler) l.box = Math.min(4, l.box + 1);
  else l.box = 1;
  const abstand = {1:3, 2:6, 3:11, 4:18}[l.box];
  l.faellig = S.zaehler + abstand;
  S.leitner[aufgabe.id] = l;


  S.verlauf.unshift({id:aufgabe.id, titel:aufgabe.titel, versuche, ohneFehler, zeit:Date.now()});
  S.verlauf = S.verlauf.slice(0, 40);
  standSpeichern();
}

function fehlerVerbuchen(ergebnis){
  S.gesamt.versuche++;
  ergebnis.typen.forEach(t => { S.fehler[t] = (S.fehler[t]||0) + 1; });
  fehlerheftArten(ergebnis.typen);
  if (ergebnis.hauptfehler){
    S.letzteFehler.push(ergebnis.hauptfehler);
    S.letzteFehler = S.letzteFehler.slice(-6);
  }
  standSpeichern();
}

/* Zwei gleiche Hauptfehler hintereinander lösen eine Übungsschleife aus */
function remediationFaellig(){
  return null;   // Aufgabenpool: keine Übungsschleifen
  if (!imLernpfad()) return null;   // Übungsschleifen nur im Lernpfad – im freien Üben wählt man selbst, was man übt
  const l = S.letzteFehler;
  if (l.length < 2) return null;
  const a = l[l.length-1], b = l[l.length-2];
  if (a !== b) return null;
  const drillId = DRILL_ZUORDNUNG[a];
  return drillId ? {typ:a, drill:drillId} : null;
}

