let KRP_AKTIV = 'ikr';
function krpSetzen(kr){
  if (!kr || !KRP_PAKETE[kr] || kr === KRP_AKTIV) return;
  const P = KRP_PAKETE[kr];
  IKR = P.IKR; VERWECHSLUNG = P.VERWECHSLUNG; STEUERKONTEN = P.STEUERKONTEN; BILANZPOSITIONEN = P.BILANZPOSITIONEN; DRILLS = P.DRILLS;
  KRP_AKTIV = kr;
}
function krpVon(a){ const m = a && a.modul && MODULE.find(x => x.id === a.modul); return m ? m.kr : null; }

/* ==========================================================================
   6 · BUCHUNGS-EDITOR
   ========================================================================== */
let aktuell = null, versuche = 0, hinweisStufe = 0, geloest = false, drillLaeuft = false;
let zeilenId = 0;

function zeileHinzu(seite, konto, betrag, fest){ return zeileHinzuIn('satz-zeilen', seite, konto, betrag, fest); }

function zeileHinzuIn(containerId, seite, konto, betrag, fest){
  const uid = 'z' + (++zeilenId);
  const div = document.createElement('div');
  div.className = 'satz-zeile' + (fest ? ' fest' : '');
  if (seite) div.dataset.seite = seite;
  div.innerHTML = `
    <div class="seite-wahl" data-uid="${uid}">
      <button type="button" data-s="soll"  class="${seite==='soll'?'an':''}"  onclick="seiteSetzen('${uid}','soll')">Soll</button>
      <button type="button" data-s="haben" class="${seite==='haben'?'an':''}" onclick="seiteSetzen('${uid}','haben')">Haben</button>
    </div>
    <div class="konto-feld">
      <input type="text" id="${uid}" class="konto-eingabe"
             value="${konto ? (zeigeNummern ? konto : kName(konto)) : ''}" autocomplete="off" spellcheck="false" ${fest?'readonly':''}
             placeholder="${zeigeNummern ? 'Kontonummer oder Name' : 'Kontoname'}"
             oninput="acTippen('${uid}')" onkeydown="acTaste(event,'${uid}')" onblur="acSchliessen('${uid}')">
      <div class="konto-name" id="name-${uid}">${konto && zeigeNummern && IKR[konto] ? IKR[konto] : ''}</div>
    </div>
    <div class="betrag-weg">
      <input type="text" class="betrag-feld" inputmode="decimal" placeholder="0,00" title="Betrag oder Rechenweg, z. B. 1800*19%" ${fest?'readonly':''}
             value="${betrag!=null?zahl(betrag):''}" oninput="summenAktualisieren()">
      <button class="weg" title="Zeile entfernen" ${fest?'style="visibility:hidden"':''}
              onclick="this.closest('.satz-zeile').remove(); summenAktualisieren()">✕</button>
    </div>`;
  document.getElementById(containerId).appendChild(div);
  if (containerId === 'satz-zeilen') summenAktualisieren();
  return div;
}

function seiteSetzen(uid, seite){
  const wahl = document.querySelector(`.seite-wahl[data-uid="${uid}"]`);
  if (!wahl) return;
  wahl.querySelectorAll('button').forEach(b => b.classList.toggle('an', b.dataset.s === seite));
  wahl.closest('.satz-zeile').dataset.seite = seite;
  summenAktualisieren();
}

function editorLeeren(){
  if (aktuell && aktuell.typ === 'bilanzwirkung'){ bilanzLeeren(); return; }
  if (aktuell && aktuell.typ === 'kontenabschluss'){ kontoLeeren(); return; }
  if (aktuell && aktuell.typ === 'bilanzaufstellung'){ inventarLeeren(); return; }
  if (aktuell && aktuell.typ === 'herstellungskosten'){ hkLeeren(); return; }
  if (aktuell && aktuell.typ === 'berechnung'){ rechnungLeeren(); return; }
  if (aktuell && aktuell.typ === 'wareneinsatz'){ kalkulationLeeren(); return; }
  if (aktuell && aktuell.typ === 'kette'){ ketteLeeren(); return; }
  if (aktuell && aktuell.typ === 'anschaffungskosten'){ akLeeren(); return; }
  if (aktuell && aktuell.typ === 'tabelle'){ tabLeeren(); return; }
  const halter = document.getElementById('satz-zeilen');
  halter.innerHTML = '';
  document.getElementById('vorgabe-halter').innerHTML = '';

  if (aktuell && aktuell.vorgabe === 'seiten'){
    document.getElementById('vorgabe-halter').innerHTML =
      '<div class="vorgabe-hinweis">Konten und Beträge sind vorgegeben. Entscheide für jede Zeile nur, ob sie ins <b>Soll</b> oder ins <b>Haben</b> gehört.</div>';
    mischen([...aktuell.muster]).forEach(z => zeileHinzu(null, z.konto, z.betrag, true));
  } else {
    zeileHinzu(); zeileHinzu();
  }
  summenAktualisieren();
}

function mischen(a){
  for (let i = a.length-1; i > 0; i--){ const j = Math.floor(Math.random()*(i+1)); [a[i],a[j]] = [a[j],a[i]]; }
  return a;
}

function eingabeLesenIn(containerId){
  const raus = [];
  document.querySelectorAll('#' + containerId + ' .satz-zeile').forEach(z => {
    const konto = z.querySelector('.konto-eingabe').value.trim();
    const bf = z.querySelector('.betrag-feld'), betrag = betragLesen(bf.value);
    const seite = z.dataset.seite;
    if (konto === '' && betrag == null) return;
    const roh = bf.value.trim(), formel = bf.dataset.formel || (typeof tabIstAusdruck === 'function' && tabIstAusdruck(roh) ? roh : '');
    raus.push({seite: seite || null, konto: kontoNormalisieren(konto), betrag: betrag == null ? 0 : betrag, roh:konto, ...(formel && betrag != null ? {formel} : {})});
  });
  return raus;
}

function eingabeLesen(){
  const raus = [];
  document.querySelectorAll('.satz-zeile').forEach(z => {
    const konto = z.querySelector('.konto-eingabe').value.trim();
    const betrag = betragLesen(z.querySelector('.betrag-feld').value);
    const seite = z.dataset.seite;
    if (konto === '' && betrag == null) return;
    raus.push({seite: seite || 'soll', konto: kontoNormalisieren(konto), betrag: betrag == null ? 0 : betrag,
               ohneSeite: !seite});
  });
  return raus;
}

/* Nutzer darf auch Kontennamen eintippen – hier wird auf die Nummer normalisiert */
function kontoNormalisieren(eingabe){
  const e = eingabe.trim();
  if (IKR[e]) return e;
  const nurNr = e.match(KRP_PAKETE[KRP_AKTIV].nrKurz ? /^(\d{2,4})(?!\d)/ : /^(\d{3,4})(?!\d)/);
  if (nurNr && IKR[nurNr[1]]) return nurNr[1];
  if (!KRP_PAKETE[KRP_AKTIV].nrKurz && nurNr && nurNr[1].length === 3 && IKR[nurNr[1] + '0']) return nurNr[1] + '0';
  const treffer = Object.entries(IKR).find(([k,n]) => n.toLowerCase() === e.toLowerCase());
  if (treffer) return treffer[0];
  // Teileingabe zulassen, solange sie eindeutig ist
  const q = e.toLowerCase();
  const kandidaten = erlaubteKonten().filter(k => IKR[k].toLowerCase().startsWith(q));
  if (kandidaten.length === 1) return kandidaten[0];
  const enthalten = erlaubteKonten().filter(k => IKR[k].toLowerCase().includes(q));
  return enthalten.length === 1 ? enthalten[0] : e;
}

function summenAktualisieren(){
  let s = 0, h = 0, offen = 0;
  document.querySelectorAll('.satz-zeile').forEach(z => {
    const b = betragLesen(z.querySelector('.betrag-feld').value) || 0;
    if (z.dataset.seite === 'soll') s += b;
    else if (z.dataset.seite === 'haben') h += b;
    else if (b) offen++;
  });
  s = runde(s); h = runde(h);
  document.getElementById('summe-soll').textContent = euro(s);
  document.getElementById('summe-haben').textContent = euro(h);
  const w = document.getElementById('waage');
  if (offen){ w.className = 'waage'; w.textContent = offen + (offen===1 ? ' Zeile ohne Seite' : ' Zeilen ohne Seite'); }
  else if (s === 0 && h === 0){ w.className = 'waage'; w.textContent = 'Beide Seiten müssen dieselbe Summe ergeben.'; }
  else if (gleichBetrag(s,h)){ w.className = 'waage gleich'; w.textContent = '⟺ ausgeglichen'; }
  else { w.className = 'waage ungleich'; w.textContent = '≠ Differenz ' + euro(Math.abs(s-h)); }
}

/* ---------- Auto-Complete ---------- */
let acIndex = -1;
/* Ohne Kontenrahmen steht nur der Bestandskonten-Vorrat der Module 1 bis 3 zur Verfügung */
function erlaubteKonten(){
  if (zeigeNummern) return Object.keys(IKR);
  // Nur Konten, die bis zum laufenden Modul eingeführt wurden
  const bis = aktuell ? MODULE.findIndex(m => m.id === aktuell.modul) : MODULE.length;
  const ids = new Set(BILANZPOSITIONEN.map(p => p.konto));
  MODULE.forEach((m, idx) => {
    if (m.nummern !== false || (bis >= 0 && idx > bis)) return;
    modulAufgaben(m.id).forEach(a => (a.soll||[]).concat(a.haben||[])
      .forEach(z => ids.add(String(z.konto).trim())));
  });
  return [...ids].filter(k => IKR[k]).sort();
}
function acTreffer(v){
  const q = v.trim().toLowerCase();
  if (!q) return [];
  return erlaubteKonten().map(k => [k, IKR[k]])
    .filter(([k,n]) => (zeigeNummern && k.startsWith(q)) || n.toLowerCase().includes(q))
    .slice(0,8);
}
function acTippen(uid){
  const inp = document.getElementById(uid);
  const treffer = acTreffer(inp.value);
  document.getElementById('name-'+uid).textContent = zeigeNummern ? (IKR[inp.value.trim()] || '') : '';
  acSchliessen(uid, true);
  if (!treffer.length) return;
  acIndex = -1;
  const box = document.createElement('div');
  box.className = 'ac'; box.id = 'ac-' + uid;
  box.innerHTML = treffer.map(([k,n],i) =>
    `<div class="ac-treffer" data-i="${i}" onmousedown="acWaehlen('${uid}','${k}')">${zeigeNummern ? `<span class="nr">${k}</span>` : ''}<span>${n}</span></div>`).join('');
  inp.parentElement.appendChild(box);
}
function acWaehlen(uid, k){
  const inp = document.getElementById(uid);
  inp.value = zeigeNummern ? k : (IKR[k] || k);
  document.getElementById('name-'+uid).textContent = zeigeNummern ? (IKR[k] || '') : '';
  acSchliessen(uid, true);
  const zeile = inp.closest('.satz-zeile');
  const betrag = zeile ? zeile.querySelector('.betrag-feld') : null;
  if (betrag) betrag.focus();
}
function acSchliessen(uid, sofort){
  const weg = () => { const b = document.getElementById('ac-'+uid); if (b) b.remove(); };
  sofort ? weg() : setTimeout(weg, 150);
}
function acTaste(ev, uid){
  const box = document.getElementById('ac-'+uid);
  if (!box){
    if (ev.key === 'Enter'){ ev.preventDefault(); satzFeldWeiter(ev.target, ev.shiftKey); }   // Enter springt weiter, geprüft wird nur mit dem Knopf
    return;
  }
  const items = [...box.querySelectorAll('.ac-treffer')];
  if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp'){
    ev.preventDefault();
    acIndex = (acIndex + (ev.key === 'ArrowDown' ? 1 : items.length-1)) % items.length;
    items.forEach((it,i) => it.classList.toggle('markiert', i === acIndex));
  } else if (ev.key === 'Enter'){
    ev.preventDefault();
    const ziel = items[acIndex >= 0 ? acIndex : 0];
    if (ziel) acWaehlen(uid, ziel.querySelector('.nr').textContent);
  } else if (ev.key === 'Escape'){ acSchliessen(uid, true); }
}
/* Rechenweg im Betragsfeld: beim Verlassen ausrechnen und merken, beim Zurückkommen wieder zeigen */
function betragFeldSchoen(el){
  const roh = el.value.trim();
  el.classList.remove('tab-ungueltig');
  if (!roh || typeof tabIstAusdruck !== 'function' || !tabIstAusdruck(roh)){ delete el.dataset.formel; el.classList.remove('tab-formel'); return; }
  const v = tabZahl(roh);
  if (v == null){ el.classList.add('tab-ungueltig'); el.title = 'Rechenweg nicht lesbar – erlaubt sind Zahlen, + − * / ( ) und %'; return; }
  el.dataset.formel = roh; el.classList.add('tab-formel'); el.title = 'Rechenweg: ' + roh.replace(/^=/, '');
  el.value = zahl(v);
}
document.addEventListener('focusout', ev => { const el = ev.target; if (el.classList && el.classList.contains('betrag-feld') && !el.readOnly) betragFeldSchoen(el); });
document.addEventListener('focusin', ev => { const el = ev.target; if (el.classList && el.classList.contains('betrag-feld') && el.dataset.formel && !el.readOnly) el.value = el.dataset.formel; });
/* Enter im Buchungssatz wie Tab: ins nächste Feld (Umschalt+Enter zurück), im letzten Feld nur ausrechnen – nie gleich prüfen */
function satzFeldWeiter(el, zurueck){
  const halter = el.closest('.satz-zeile') && el.closest('.satz-zeile').parentElement;
  if (!halter){ el.blur(); return; }
  const felder = [...halter.querySelectorAll('.konto-eingabe, .betrag-feld')].filter(f => !f.readOnly && !f.disabled);
  const ziel = felder[felder.indexOf(el) + (zurueck ? -1 : 1)];
  if (ziel){ ziel.focus(); if (ziel.select) ziel.select(); } else el.blur();
}
document.addEventListener('keydown', ev => {
  if (ev.key === 'Enter' && ev.target.classList && ev.target.classList.contains('betrag-feld')){
    ev.preventDefault(); satzFeldWeiter(ev.target, ev.shiftKey);
  }
});

/* ==========================================================================
   7 · AUFGABEN-ABLAUF
   ========================================================================== */
/* Schlagwörter, die die Lösung vorwegnehmen – sie zählen weiter für das
   Kompetenz-Radar, erscheinen aber nicht auf der Aufgabenkarte. */
const VERRAET_LOESUNG = new Set([
  'Aktivtausch','Passivtausch','Bilanzverlängerung','Bilanzverkürzung','Aufwand','Ertrag'
]);

function aufgabeLaden(){ aufgabeSetzen(naechsteAufgabe()); }

/* ---------- Labor-Aufgaben: Werkstatt aus Labor/Labor.html eingebettet (LABOR_QUELLE), Fortschritt per postMessage ---------- */
function laborSetzen(inst){
  const halter = document.getElementById('labor-halter'), stand = document.getElementById('labor-stand');
  if (!halter) return;
  halter.innerHTML = ''; stand.textContent = ''; stand.className = 'labor-stand';
  if (!inst) return;
  if (!LABOR_QUELLE){ halter.innerHTML = '<p class="leer">Die Werkstatt ist in dieser Datei nicht enthalten.</p>'; return; }
  const f = document.createElement('iframe');
  f.title = 'Labor: ' + (inst.titel || inst.labor);
  f.srcdoc = LABOR_QUELLE.replace('<head>', '<head><script>window.LABOR_SOLO = ' + JSON.stringify(inst.labor) + '; window.LABOR_VARIANTE = ' + JSON.stringify(inst.laborVariante || '') + ';<\/script>');
  halter.appendChild(f);
  stand.textContent = 'Erfülle die Aufträge in der Werkstatt – sie haken sich automatisch ab.';
}
window.addEventListener('message', ev => {
  const d = ev.data; if (!d || d.quelle !== 'labor' || !aktuell || aktuell.typ !== 'labor' || d.labor !== aktuell.labor) return;
  const f = document.querySelector('#labor-halter iframe'), stand = document.getElementById('labor-stand');
  if (d.hoehe && f) f.style.height = (d.hoehe + 8) + 'px';
  if (d.gesamt != null && stand){
    stand.textContent = d.fertig ? '✓ Alle ' + d.gesamt + ' Aufträge erledigt – Labor abgeschlossen.' : d.erledigt + ' von ' + d.gesamt + ' Aufträgen erledigt';
    stand.classList.toggle('fertig', !!d.fertig);
  }
  if (d.fertig && !geloest){
    geloest = true; versuche = 1;
    ergebnisVerbuchen(aktuell, {korrekt:true, typen:[], befunde:[]}, 1);
    standSpeichern();
    const fz = document.querySelector('#fall-zaehler .fall-status'); if (fz) fz.outerHTML = fallStatusHTML(aktuell);
  }
});
function aufgabeSetzen(inst){
  aktuell = inst;
  versuche = 0; hinweisStufe = 0; geloest = false;
  document.getElementById('hinweis-halter').innerHTML = '';
  document.getElementById('diagnose-halter').innerHTML = '';
  document.getElementById('bilanz-echo').textContent = '';
  const bp = document.getElementById('btn-pruefen'); bp.disabled = false;
  const bh = document.getElementById('btn-hinweis');
  bh.disabled = false; bh.textContent = 'Hinweis anfordern (1/3)';
  const bnz = document.getElementById('btn-neuzahlen');
  if (bnz){ bnz.disabled = false; bnz.textContent = 'Neue Zahlen'; bnz.style.display = nzMoeglich(inst) ? '' : 'none'; }
  modulleisteZeichnen();
  gruppenLeisteZeichnen();

  const mod = aktuell ? modulFinden(aktuell.modul) : null;
  zeigeNummern = !(mod && mod.nummern === false);
  const typ = aktuell ? aktuell.typ : 'buchungssatz';
  document.getElementById('editor-karte').style.display   = typ === 'buchungssatz' ? '' : 'none';
  document.getElementById('bilanz-karte').style.display   = typ === 'bilanzwirkung' ? '' : 'none';
  document.getElementById('konto-karte').style.display    = typ === 'kontenabschluss' ? '' : 'none';
  document.getElementById('inventar-karte').style.display = typ === 'bilanzaufstellung' ? '' : 'none';
  document.getElementById('hk-karte').style.display = typ === 'herstellungskosten' ? '' : 'none';
  document.getElementById('rechnung-karte').style.display  = typ === 'berechnung' ? '' : 'none';
  document.getElementById('kalkulation-karte').style.display = typ === 'wareneinsatz' ? '' : 'none';
  document.getElementById('kette-karte').style.display = typ === 'kette' ? '' : 'none';
  document.getElementById('ak-karte').style.display = typ === 'anschaffungskosten' ? '' : 'none';
  document.getElementById('tabelle-karte').style.display = typ === 'tabelle' ? '' : 'none';
  document.getElementById('labor-karte').style.display = typ === 'labor' ? '' : 'none';
  document.getElementById('aktionsleiste').style.display = typ === 'kette' || typ === 'labor' ? 'none' : '';
  laborSetzen(typ === 'labor' ? inst : null);
  bp.textContent = typ === 'tabelle' ? 'Aufgabe prüfen'
    : typ === 'anschaffungskosten' ? 'Anschaffungskosten prüfen'
    : typ === 'wareneinsatz' ? 'Warenrohgewinn prüfen'
    : typ === 'berechnung' ? 'Antwort prüfen'
    : typ === 'bilanzwirkung' ? 'Bilanzwirkung prüfen'
    : typ === 'kontenabschluss' ? 'T-Konto prüfen'
    : typ === 'bilanzaufstellung' ? 'Bilanz prüfen'
    : typ === 'herstellungskosten' ? 'Zuordnung prüfen'
    : (aktuell && aktuell.vorgabe === 'seiten' ? 'Zuordnung prüfen' : 'Buchungssatz prüfen');
  editorLeeren();

  if (!aktuell){
    document.getElementById('fall-titel').textContent = 'Kein Fall verfügbar';
    document.getElementById('fall-text').textContent = 'Für das freigeschaltete Modul liegen keine Aufgaben vor. Importiere unter „Aufgaben“ eine JSON-Datei oder setze auf die Standardbank zurück.';
    document.getElementById('fall-marker').innerHTML = '';
    document.getElementById('fall-zaehler').textContent = '';
    return;
  }

  const m = modulFinden(aktuell.modul);
  document.getElementById('modul-merke').innerHTML = (m && m.pruefHinweis ? `<div class="modul-pruefhinweis"><span class="lbl">Prüfungshinweis</span>${m.pruefHinweis}</div>` : '') + (!m ? '' : (m.merkeModul
    ? `<div class="modul-merke"><button type="button" class="wk-knopf" onclick="wissenOeffnen(${jsArg(m.id)})" title="Das Wichtigste zu diesem Modul zum Nachlesen und Drucken">📖 Wissen kompakt</button><span class="lbl">Für dieses Modul gilt</span>${m.merkeModul}</div>`
    : `<div class="wk-zeile"><button type="button" class="wk-knopf" onclick="wissenOeffnen(${jsArg(m.id)})" title="Das Wichtigste zu diesem Modul zum Nachlesen und Drucken">📖 Wissen kompakt</button></div>`));
  document.getElementById('fall-titel').textContent = aktuell.titel;
  document.getElementById('fall-text').innerHTML = aktuell.text;
  if (m){
    const kern = modulKern(m.id).map(a => a.id);
    const sicher = modulStand(m.id).geloest.filter(x => kern.includes(x)).length;
    document.getElementById('fall-zaehler').innerHTML =
      `Modul ${m.nr} · ${sicher} von ${kern.length} Fällen sicher ${medailleHTML(medaille(m.id).stufe)}<br>${fallStatusHTML(aktuell)}`;
  } else document.getElementById('fall-zaehler').textContent = '';
  // Wiedervorlagen aus früheren Modulen zählen nicht als Modulwechsel
  if (!aktuell.variante){
    if (!S.modulWahl && S.letzterFallModul && S.letzterFallModul !== aktuell.modul){
      const vorher = modulFinden(S.letzterFallModul);
      modulEcho(`Modul ${vorher ? vorher.nr : '?'} ist durchgearbeitet. Weiter mit Modul ${m.nr} – ${m.titel}: ${m.ziel}`, 'info');
    }
    S.letzterFallModul = aktuell.modul;
    standSpeichern();
  }

  blaetternZeichnen();

  document.getElementById('fall-marker').innerHTML =
    (aktuell.gruppe ? `<span class="tag bereich">${aktuell.gruppe}</span>` : '') +
    (aktuell.vorgabe === 'seiten' ? '<span class="tag">Vorübung · Zuordnung</span>' : '') +
    stufenSprungHTML() +
    (aktuell.variante ? `<span class="tag">Wiedervorlage · ${aktuell.typ === 'kontenabschluss' ? 'andere Reihenfolge' : 'neue Zahlen'}</span>` : '') +
    '';
}

/* ---------- Beispiele eines Moduls durchblättern ---------- */
let blaetterIndex = null;

function modulListe(id){
  return modulAufgaben(id).slice().sort((a,b) => (a.stufe ?? 2) - (b.stufe ?? 2));
}

/* Gruppen innerhalb eines Moduls, in der Reihenfolge ihres ersten Auftretens */
function modulGruppen(id){
  const raus = [];
  modulListe(id).forEach(a => { if (a.gruppe && !raus.includes(a.gruppe)) raus.push(a.gruppe); });
  return raus;
}
/* Die Liste, durch die geblättert wird – ganzes Modul oder nur die gewählte Gruppe */
/* Sprungmarken zu den Stufen des aktuellen Moduls (bzw. Bereichs) */
function stufenListe(){
  if (!aktuell) return [];
  const liste = (S.modulWahl === aktuell.modul) ? blaetterListe() : modulListe(aktuell.modul);
  return liste;
}
const LABOR_STUFE = 9;
const FREI_STUFE = 8;   // offene Fragen (Freitext mit Erwartungshorizont) – eigene Stufe, damit man sie gezielt ansteuern kann
const stufeName = n => n === 0 ? 'Theorie' : n === LABOR_STUFE ? 'Labor' : n === FREI_STUFE ? 'Offene Frage' : 'Stufe ' + n;
function stufenSprungHTML(){
  const liste = stufenListe();
  const stufen = [...new Set(liste.map(a => a.stufe ?? 2))].sort((a, b) => (a === 0) - (b === 0) || a - b);
  const jetzt = aktuell.stufe ?? 2;
  if (stufen.length < 2) return `<span class="tag ${jetzt === LABOR_STUFE ? 'labor' : 'stufe'}">${stufeName(jetzt)}</span>`;
  return `<span class="stufen-sprung" role="group" aria-label="Zur Stufe springen">` + stufen.map(n =>
    `<button type="button" class="tag stufe-knopf${n === jetzt ? ' stufe' : ''}${n === LABOR_STUFE ? ' labor' : ''}" aria-pressed="${n === jetzt}" onclick="stufeSpringen(${n})" title="${n === jetzt ? 'Aktuelle Stufe' : 'Zur ersten Aufgabe dieser Stufe'}">${stufeName(n)}</button>`).join('') + `</span>`;
}
function stufeSpringen(n){
  const liste = stufenListe();
  const i = liste.findIndex(a => (a.stufe ?? 2) === n);
  if (i < 0) return;
  if ((aktuell.stufe ?? 2) === n && liste[i].id === aktuell.id) return;
  if (S.modulWahl !== aktuell.modul){ S.modulWahl = aktuell.modul; S.letztesModul = aktuell.modul; S.gruppenWahl = null; standSpeichern(); }
  blaetterIndex = i;
  aufgabeSetzen(instanzBauen(liste[i], false));
}

function blaetterListe(){
  const liste = modulListe(S.modulWahl);
  return S.gruppenWahl ? liste.filter(a => a.gruppe === S.gruppenWahl) : liste;
}

/* Ein String, der gefahrlos in onclick="..." als JS-Argument stehen kann:
   einfache Anführungszeichen und HTML-Sonderzeichen werden maskiert. */
function jsArg(text){
  return "'" + String(text).replace(/\\/g,'\\\\').replace(/'/g,"\\'")
    .replace(/&/g,'&amp;').replace(/"/g,'&quot;') + "'";
}

function gruppenLeisteZeichnen(){
  const halter = document.getElementById('gruppen-leiste');
  if (!halter) return;
  // Auch im Automatikbetrieb sichtbar – für das Modul, aus dem der aktuelle Fall stammt
  const modul = S.modulWahl || (aktuell ? aktuell.modul : null);
  const gruppen = modul ? modulGruppen(modul) : [];
  if (gruppen.length < 2){ halter.innerHTML = ''; return; }
  halter.innerHTML = '<span class="lbl">Bereich</span>'
    + `<button class="gruppe-chip ${S.gruppenWahl ? '' : 'aktiv'}" onclick="gruppeWaehlen(null)">alle</button>`
    + gruppen.map(g => `<button class="gruppe-chip ${S.gruppenWahl === g ? 'aktiv' : ''}"
        onclick="gruppeWaehlen(${jsArg(g)})">${g}</button>`).join('');
}

function gruppeWaehlen(g){
  const modul = S.modulWahl || (aktuell ? aktuell.modul : null);
  if (!modul || !modulFrei(modul)) return;
  // Ein Bereich gehört zu einem Modul – also wird dieses zugleich festgehalten
  S.modulWahl = modul; S.letztesModul = modul;
  S.gruppenWahl = (S.gruppenWahl === g) ? null : g;
  blaetterIndex = null;
  standSpeichern();
  const liste = blaetterListe();
  if (liste.length) aufgabeSetzen(instanzBauen(liste[0], false));
  else aufgabeLaden();
  const m = modulFinden(modul);
  modulEcho(S.gruppenWahl
    ? `Modul ${m.nr}, Bereich „${S.gruppenWahl}“ – nur noch Aufgaben von dort, auch beim Blättern.`
    : `Modul ${m.nr} festgehalten, alle Bereiche.`);
}

function blaetternZeichnen(){
  const halter = document.getElementById('blaettern');
  if (!halter) return;
  if (!S.modulWahl || !aktuell){ halter.innerHTML = ''; return; }
  const liste = blaetterListe();
  const i = liste.findIndex(a => a.id === aktuell.id);
  if (liste.length < 2 || i < 0){ halter.innerHTML = ''; return; }
  const bereich = (!S.gruppenWahl && aktuell.gruppe) ? aktuell.gruppe : '';
  halter.innerHTML =
    `<button type="button" title="vorheriges Beispiel" onclick="aufgabeBlaettern(-1)">◀</button>
     <span class="stand">Beispiel ${i+1} von ${liste.length}</span>
     <button type="button" title="nächstes Beispiel" onclick="aufgabeBlaettern(1)">▶</button>${bereich ? `<span class="bereich">${bereich}</span>` : ''}`;
}

/* Blättert der Reihe nach durch die Aufgaben des festgehaltenen Moduls –
   ohne Wiedervorlage, ohne Auswahl nach Fehlerprofil. */
function aufgabeBlaettern(schritt){
  if (!S.modulWahl) return;
  const liste = blaetterListe();
  if (!liste.length) return;
  let i = aktuell ? liste.findIndex(a => a.id === aktuell.id) : -1;
  if (i < 0) i = blaetterIndex != null ? blaetterIndex : 0;
  i = (i + schritt + liste.length) % liste.length;
  blaetterIndex = i;
  aufgabeSetzen(instanzBauen(liste[i], false));
}

