  if (!box){ box = document.createElement('div'); box.className = 'tab-ac'; td.appendChild(box); }
  box.innerHTML = treffer.map((x, n) => `<div class="tab-ac-t${n === 0 && el.value ? ' markiert' : ''}" data-id="${x.id}">${tEsc(x.t)}</div>`).join('');
