  const opts = f[0].optionen.map(o => o.text);
  if (opts.length !== f.length || !opts.every((t, n) => new RegExp('^\\s*' + (n + 1) + '\\.').test(t))) return false;
  if (f.some(x => x.optionen.map(o => o.text).join('|') !== opts.join('|'))) return false;
