  // Zuordnungsaufgaben (nur Auswahlfelder, keine Tabelle): passende Überschrift
  const k = document.getElementById('tabelle-karte'), ab = k && k.querySelector('.augenbraue'), hi = k && k.querySelector('.tab-hilfe'), zu = !(aktuell.tabelle && aktuell.tabelle.zeilen && aktuell.tabelle.zeilen.length);
  if (ab) ab.textContent = zu ? 'Zuordnen' : 'Tabelle ausfüllen';
  if (hi) hi.textContent = zu ? (tabIstReihe(aktuell) ? 'Bringe die Schritte in die richtige Reihenfolge.' : 'Wähle für jeden Punkt die passende Antwort.') : 'Felder, in die nichts gehört, bleiben leer.';
