  document.querySelectorAll('#tab-halter .tab-wahlzeile .tab-optionen').forEach(el => {
    const inp = el.querySelector('.tab-wahl'); const s = inp ? r.st[inp.dataset.k] : null;
    el.className = 'tab-optionen' + (s ? ' st-' + s : '');
  });
  const istWahl = k => (zellen[k] || {}).art === 'wahl', istFrei = k => (zellen[k] || {}).art === 'frei';
  const zaehl = s => Object.keys(r.st).filter(k => r.st[k] === s && !istWahl(k) && !istFrei(k)).length;
  // Freitext: nach dem ersten Prüfen den Erwartungshorizont aufdecken (Selbstkontrolle)
  const freiK = Object.keys(r.st).filter(istFrei);
  const kurz = k => r.st[k] === 'frei' && String(eingabe[k] || '').trim().split(/\s+/).length < 8;   // erst eine echte Antwort, dann der Erwartungshorizont
  freiK.forEach(k => { if (r.st[k] !== 'fehlt' && !kurz(k)){ const b = document.querySelector(`#tab-halter .tab-frei-eh[data-k="${k}"]`); if (b) b.hidden = false; const ez = document.querySelector(`#tab-halter .tab-frei-einzel[data-k="${k}"]`); if (ez) ez.hidden = true; }
    const bl = document.querySelector(`#tab-halter .tab-freitext[data-k="${k}"]`); if (bl) bl.closest('.tab-frei-block').className = 'tab-frei-block' + (r.st[k] === 'frei' ? '' : ' st-' + r.st[k]); });
  const freiOffen = freiK.filter(k => r.st[k] !== 'ok');
  const wahlK = Object.keys(r.st).filter(istWahl), wahlFalsch = wahlK.filter(k => r.st[k] !== 'ok');
  const n = {ok:zaehl('ok'), ff:zaehl('ff'), falsch:zaehl('falsch'), fehlt:zaehl('fehlt'), zuviel:zaehl('zuviel')};
  const korrekt = !n.ff && !n.falsch && !n.fehlt && !n.zuviel && !wahlFalsch.length && !freiOffen.length;
  // Nur noch die Selbstkontrolle offen (alles andere richtig): das Aufdecken des Erwartungshorizonts ist kein Versuch
  const selbstkontrolle = !korrekt && freiOffen.length > 0 && !n.ff && !n.falsch && !n.fehlt && !n.zuviel && !wahlFalsch.length && freiOffen.every(k => r.st[k] === 'frei');
  const b = [];
