  return {punkte:r.punkte, max:r.max, teile:[{art:'tabelle', titel:'Tabelle', inst, eingabe:ein, formeln:(antwort && antwort.r) || null, st:r.st, soll:r.soll, mw:r.mw, punkte:r.punkte, max:r.max, abzug:r.abzug}]};
