      + ' grid-template-columns:repeat(10, minmax(0, 1fr)); gap:3px; padding:5px max(4px, env(safe-area-inset-right)) calc(5px + env(safe-area-inset-bottom)) max(4px, env(safe-area-inset-left));'
      + ' background:#2b2f3a; box-shadow:0 -2px 8px rgba(0,0,0,.25); overflow:hidden}'
